<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use App\Traits\BelongsToCompany;
class SalesInvoice extends Model {use BelongsToCompany; protected $guarded=[]; protected function casts():array{return ['invoice_date'=>'date','due_date'=>'date','jofotara_required'=>'boolean'];} public function lines(){return $this->hasMany(SalesInvoiceLine::class);} public function contact(){return $this->belongsTo(Contact::class);} public function journal(){return $this->belongsTo(Journal::class);} public function currency(){return $this->belongsTo(Currency::class);} public function credits(){return $this->hasMany(self::class,'credit_of_invoice_id');}}
